نقش سازمانی: مدیر مالی (cfo)

درخواست کاربر:
چرخهٔ تبدیل وجه نقد ما نسبت به فصل قبل 21 روز بلندتر شده و پول در حساب‌های دریافتنی خوابیده. دقیقاً کجای زنجیرهٔ نقد شکسته؟ می‌خواهم روی همان نقطه تمرکز کنم. (مدیر مالی — تولیدی قطعات خودرو)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "working_capital_breakdown",
      "description": "اجزای سرمایه در گردش و روزهای هر جزء",
      "dimensions": [
        "component",
        "period"
      ],
      "measures": [
        "amount",
        "days"
      ]
    },
    {
      "dataset": "receivables_aging",
      "description": "سن مطالبات به تفکیک مشتری و بازهٔ سنی",
      "dimensions": [
        "customer",
        "aging_bucket"
      ],
      "measures": [
        "balance"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "ccc",
      "description": "چرخهٔ تبدیل وجه نقد",
      "formula": "dio + dso - dpo",
      "unit": "روز",
      "dimensions": [
        "period"
      ]
    },
    {
      "metric": "dso",
      "description": "دورهٔ وصول مطالبات",
      "formula": "مطالبات / فروش روزانه",
      "unit": "روز",
      "dimensions": [
        "customer",
        "period"
      ]
    },
    {
      "metric": "dio",
      "description": "دورهٔ گردش موجودی",
      "formula": "موجودی / بهای تمام‌شدهٔ روزانه",
      "unit": "روز",
      "dimensions": [
        "period"
      ]
    },
    {
      "metric": "dpo",
      "description": "دورهٔ پرداخت بستانکاران",
      "formula": "بستانکاران / بهای تمام‌شدهٔ روزانه",
      "unit": "روز",
      "dimensions": [
        "period"
      ]
    }
  ],
  "business_context": [
    "شرکت تولیدی-بازرگانی میانه‌حجم؛ فروش عمدتاً نسیه به شرکت‌های صنعتی و بخشی خرد",
    "دورهٔ حسابداری ماهانه؛ گزارش‌ها تا پایان همان ماه در دسترس‌اند",
    "تأمین مالی اصلی از تسهیلات بانکی کوتاه‌مدت و اعتبار تأمین‌کنندگان"
  ]
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "ccc"
    ],
    "period": [
      "prev_quarter",
      "curr_quarter"
    ],
    "comparison": "quarter_over_quarter"
  }
}

TOOL_OBSERVATION:
{
  "ccc_days": {
    "prev_quarter": 31,
    "curr_quarter": 52,
    "change": 21
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "working_capital_breakdown",
    "filters": {
      "period": [
        "prev_quarter",
        "curr_quarter"
      ]
    }
  }
}

TOOL_OBSERVATION:
{
  "components_days": {
    "dio": {
      "prev": 19,
      "curr": 23
    },
    "dso": {
      "prev": 40,
      "curr": 63
    },
    "dpo": {
      "prev": 28,
      "curr": 34
    }
  },
  "receivables_m_toman": {
    "prev": 800,
    "curr": 1260
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "receivables_aging",
    "filters": {
      "period": "curr_quarter"
    }
  }
}

TOOL_OBSERVATION:
{
  "aging_top": {
    "مشتری دولتی X": {
      "balance_m_toman": 819,
      "aging_days": 91,
      "share_of_new_sales_pct": 40
    },
    "سایر مشتریان": {
      "balance_m_toman": 441,
      "aging_days": 30
    }
  },
  "note": "قرارداد جدید سه‌ماهه با مشتری دولتی X با دورهٔ پرداخت ۹۰ روز و بدون ضمانت‌نامه بانکی؛ سهم 40٪ از فروش نسیهٔ جدید"
}

نقش سازمانی: مدیر مالی (cfo)

درخواست کاربر:
به‌عنوان مدیرعامل می‌خواهم بدانم مهم‌ترین ریسک مالی این ماه از نگاه تو چیست و کجا باید تمرکز کنیم. (مدیر مالی در گفتگو با مدیرعامل — صنایع شیمیایی)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "receivables_aging",
      "description": "سن مطالبات به تفکیک مشتری و بازهٔ سنی",
      "dimensions": [
        "customer",
        "aging_bucket"
      ],
      "measures": [
        "balance"
      ]
    },
    {
      "dataset": "sales_by_product",
      "description": "فروش و حاشیه به تفکیک محصول",
      "dimensions": [
        "product",
        "period"
      ],
      "measures": [
        "sales",
        "gross_margin_pct"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "operating_profit",
      "description": "سود عملیاتی",
      "formula": "حاشیهٔ ناخالص - هزینه‌های عملیاتی",
      "unit": "میلیون تومان",
      "dimensions": [
        "period"
      ]
    },
    {
      "metric": "operating_cash_flow",
      "description": "جریان نقد عملیاتی",
      "formula": "دریافت‌ها از عملیات - پرداخت‌های عملیاتی",
      "unit": "میلیون تومان",
      "dimensions": [
        "period"
      ]
    },
    {
      "metric": "dso",
      "description": "دورهٔ وصول مطالبات",
      "formula": "مطالبات / فروش روزانه",
      "unit": "روز",
      "dimensions": [
        "customer",
        "period"
      ]
    }
  ],
  "business_context": [
    "شرکت تولیدی-بازرگانی میانه‌حجم؛ فروش عمدتاً نسیه به شرکت‌های صنعتی و بخشی خرد",
    "دورهٔ حسابداری ماهانه؛ گزارش‌ها تا پایان همان ماه در دسترس‌اند",
    "تأمین مالی اصلی از تسهیلات بانکی کوتاه‌مدت و اعتبار تأمین‌کنندگان"
  ]
}

TOOL_CALL:
{
  "tool": "compare_periods",
  "arguments": {
    "metric": "operating_profit",
    "period_a": "prev_quarter",
    "period_b": "curr_quarter"
  }
}

TOOL_OBSERVATION:
{
  "operating_profit": {
    "prev": 125,
    "curr": 170,
    "growth_pct": 36
  }
}

TOOL_CALL:
{
  "tool": "compare_periods",
  "arguments": {
    "metric": "operating_cash_flow",
    "period_a": "prev_quarter",
    "period_b": "curr_quarter"
  }
}

TOOL_OBSERVATION:
{
  "operating_cash_flow": {
    "prev": 100,
    "curr": -130,
    "note": "منفی شدن هم‌زمان با رشد فروش نسیه"
  }
}

TOOL_CALL:
{
  "tool": "get_top_bottom",
  "arguments": {
    "metric": "dso",
    "dimension": "customer",
    "n": 3,
    "order": "desc"
  }
}

TOOL_OBSERVATION:
{
  "top_dso": [
    {
      "customer": "مشتری بزرگ الف",
      "dso_days": 90,
      "share_of_sales_pct": 33
    }
  ]
}

نقش سازمانی: مدیر مالی (cfo)

درخواست کاربر:
سود عملیاتی این ماه نسبت به ماه قبل حدود 13٪ کم شده در حالی که فروش تقریباً ثابت است. دقیقاً کدام ردیف باعث افت شده؟ (مدیر مالی — فرآوری لبنی)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "income_statement",
      "description": "صورت سود و زیان دوره به تفکیک خط",
      "dimensions": [
        "period",
        "line"
      ],
      "measures": [
        "amount"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "bad_debt_provision",
      "description": "ذخیرهٔ مطالبات مشکوک‌الوصول",
      "formula": "ذخیرهٔ ثبت‌شده در دوره",
      "unit": "میلیون تومان",
      "dimensions": [
        "period"
      ]
    },
    {
      "metric": "operating_profit",
      "description": "سود عملیاتی",
      "formula": "حاشیهٔ ناخالص - هزینه‌های عملیاتی",
      "unit": "میلیون تومان",
      "dimensions": [
        "period"
      ]
    }
  ],
  "business_context": [
    "شرکت تولیدی-بازرگانی میانه‌حجم؛ فروش عمدتاً نسیه به شرکت‌های صنعتی و بخشی خرد",
    "دورهٔ حسابداری ماهانه؛ گزارش‌ها تا پایان همان ماه در دسترس‌اند"
  ]
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "income_statement",
    "filters": {
      "period": [
        "prev_month",
        "curr_month"
      ]
    }
  }
}

TOOL_OBSERVATION:
{
  "income_statement": {
    "prev_month": {
      "sales": 950,
      "gross_profit": 294,
      "opex": 170,
      "operating_profit": 124
    },
    "curr_month": {
      "sales": 978,
      "gross_profit": 303,
      "opex": 195,
      "operating_profit": 108
    }
  }
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "bad_debt_provision"
    ],
    "period": "curr_month",
    "comparison": "prev_month"
  }
}

TOOL_OBSERVATION:
{
  "bad_debt_provision": {
    "curr_month": 16,
    "prev_month": 0,
    "note": "ذخیرهٔ کامل مطالبات یک مشتری ورشکسته (یکجا)"
  }
}

نقش سازمانی: مدیر مالی (cfo)

درخواست کاربر:
موجودی نقد ما چند ماه است کم می‌شود و یکی از اعضای هیئت می‌گوید تا سه ماه دیگر به صفر می‌رسد و باید فوری خط اعتباری بگیریم. این پیش‌بینی چقدر معتبر است؟ (مدیر مالی — پخش مواد اولیه)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "monthly_cash_position",
      "description": "موجودی نقد پایان ماه",
      "dimensions": [
        "month"
      ],
      "measures": [
        "balance"
      ]
    },
    {
      "dataset": "cash_flow_statement",
      "description": "صورت جریان وجوه نقد دوره به تفکیک بخش",
      "dimensions": [
        "period",
        "section"
      ],
      "measures": [
        "amount"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "cash_balance",
      "description": "موجودی نقد پایان دوره",
      "formula": "جمع ورودی و خروجی‌های نقد",
      "unit": "میلیون تومان",
      "dimensions": [
        "period"
      ]
    }
  ],
  "business_context": [
    "شرکت تولیدی-بازرگانی میانه‌حجم؛ فروش عمدتاً نسیه به شرکت‌های صنعتی و بخشی خرد",
    "دورهٔ حسابداری ماهانه؛ گزارش‌ها تا پایان همان ماه در دسترس‌اند",
    "تأمین مالی اصلی از تسهیلات بانکی کوتاه‌مدت و اعتبار تأمین‌کنندگان"
  ]
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "cash_balance"
    ],
    "period": "last_4_months",
    "comparison": null
  }
}

TOOL_OBSERVATION:
{
  "cash_balance_monthly": [
    {
      "month": "فروردین",
      "end_balance_m_toman": 350
    },
    {
      "month": "اردیبهشت",
      "end_balance_m_toman": 326
    },
    {
      "month": "خرداد",
      "end_balance_m_toman": 302
    },
    {
      "month": "تیر",
      "end_balance_m_toman": 278
    }
  ]
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "cash_flow_statement",
    "filters": {
      "period": "last_4_months",
      "section": "operating"
    }
  }
}

