      "dimensions": [
        "period",
        "section"
      ],
      "measures": [
        "amount"
      ]
    },
    {
      "dataset": "monthly_cash_position",
      "description": "موجودی نقد پایان ماه",
      "dimensions": [
        "month"
      ],
      "measures": [
        "balance"
      ]
