    {
      "metric": "operating_profit",
      "description": "سود عملیاتی",
      "formula": "حاشیهٔ ناخالص - هزینه‌های عملیاتی",
      "unit": "میلیون تومان",
      "dimensions": [
        "period"
      ]
    },
    {
      "metric": "cash_balance",
      "description": "موجودی نقد پایان دوره",
      "formula": "جمع ورودی و خروجی‌های نقد",
      "unit": "میلیون تومان",
      "dimensions": [
        "period"
