سود عملیاتی این ماه نسبت به ماه قبل حدود 32٪ کم شده در حالی که فروش تقریباً ثابت است. دقیقاً کدام ردیف باعث افت شده؟ (مدیر مالی — تولیدی قطعات خودرو)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "income_statement",
      "description": "صورت سود و زیان دوره به تفکیک خط",
      "dimensions": [
        "period",
        "line"
      ],
      "measures": [
        "amount"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "bad_debt_provision",
      "description": "ذخیرهٔ مطالبات مشکوک‌الوصول",
      "formula": "ذخیرهٔ ثبت‌شده در دوره",
      "unit": "میلیون تومان",
      "dimensions": [
        "period"
      ]
    },
    {
      "metric": "operating_profit",
      "description": "سود عملیاتی",
      "formula": "حاشیهٔ ناخالص - هزینه‌های عملیاتی",
      "unit": "میلیون تومان",
      "dimensions": [
        "period"
      ]
    }
  ],
  "business_context": [
    "شرکت تولیدی-بازرگانی میانه‌حجم؛ فروش عمدتاً نسیه به شرکت‌های صنعتی و بخشی خرد",
    "دورهٔ حسابداری ماهانه؛ گزارش‌ها تا پایان همان ماه در دسترس‌اند"
  ]
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "income_statement",
    "filters": {
      "period": [
        "prev_month",
        "curr_month"
      ]
    }
  }
}

TOOL_OBSERVATION:
{
  "income_statement": {
    "prev_month": {
      "sales": 790,
      "gross_profit": 221,
      "opex": 110,
      "operating_profit": 111
    },
    "curr_month": {
      "sales": 790,
      "gross_profit": 221,
      "opex": 146,
      "operating_profit": 75
    }
  }
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "bad_debt_provision"
    ],
    "period": "curr_month",
    "comparison": "prev_month"
  }
}

TOOL_OBSERVATION:
{
  "bad_debt_provision": {
    "curr_month": 36,
    "prev_month": 0,
    "note": "ذخیرهٔ کامل مطالبات یک مشتری ورشکسته (یکجا)"
  }
}

نقش سازمانی: مدیر مالی (cfo)

درخواست کاربر:
چرخهٔ تبدیل وجه نقد ما نسبت به فصل قبل 33 روز بلندتر شده و پول در حساب‌های دریافتنی خوابیده. دقیقاً کجای زنجیرهٔ نقد شکسته؟ می‌خواهم روی همان نقطه تمرکز کنم. (مدیر مالی — صنایع شیمیایی)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "working_capital_breakdown",
      "description": "اجزای سرمایه در گردش و روزهای هر جزء",
      "dimensions": [
        "component",
        "period"
      ],
      "measures": [
        "amount",
        "days"
      ]
    },
    {
      "dataset": "receivables_aging",
      "description": "سن مطالبات به تفکیک مشتری و بازهٔ سنی",
      "dimensions": [
        "customer",
        "aging_bucket"
      ],
      "measures": [
        "balance"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "ccc",
      "description": "چرخهٔ تبدیل وجه نقد",
      "formula": "dio + dso - dpo",
      "unit": "روز",
      "dimensions": [
        "period"
      ]
    },
    {
      "metric": "dso",
      "description": "دورهٔ وصول مطالبات",
      "formula": "مطالبات / فروش روزانه",
      "unit": "روز",
      "dimensions": [
        "customer",
        "period"
      ]
    },
    {
      "metric": "dio",
      "description": "دورهٔ گردش موجودی",
      "formula": "موجودی / بهای تمام‌شدهٔ روزانه",
      "unit": "روز",
      "dimensions": [
        "period"
      ]
    },
    {
      "metric": "dpo",
      "description": "دورهٔ پرداخت بستانکاران",
      "formula": "بستانکاران / بهای تمام‌شدهٔ روزانه",
      "unit": "روز",
      "dimensions": [
        "period"
      ]
    }
  ],
  "business_context": [
    "شرکت تولیدی-بازرگانی میانه‌حجم؛ فروش عمدتاً نسیه به شرکت‌های صنعتی و بخشی خرد",
    "دورهٔ حسابداری ماهانه؛ گزارش‌ها تا پایان همان ماه در دسترس‌اند",
    "تأمین مالی اصلی از تسهیلات بانکی کوتاه‌مدت و اعتبار تأمین‌کنندگان"
  ]
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "ccc"
    ],
    "period": [
      "prev_quarter",
      "curr_quarter"
    ],
    "comparison": "quarter_over_quarter"
  }
}

TOOL_OBSERVATION:
{
  "ccc_days": {
    "prev_quarter": 30,
    "curr_quarter": 63,
    "change": 33
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "working_capital_breakdown",
    "filters": {
      "period": [
        "prev_quarter",
        "curr_quarter"
      ]
    }
  }
}

TOOL_OBSERVATION:
