جریان نقد عملیاتی هفتهٔ گذشته یک‌باره منفی بزرگ شده و مدیرعامل نگران است که روند بد شده. ببین این جهش چیست و آیا تکرار می‌شود؟ (مدیر مالی — صنایع شیمیایی)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "cash_flow_statement",
      "description": "صورت جریان وجوه نقد دوره به تفکیک بخش",
      "dimensions": [
        "period",
        "section"
      ],
      "measures": [
        "amount"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "operating_cash_flow",
      "description": "جریان نقد عملیاتی",
      "formula": "دریافت‌ها از عملیات - پرداخت‌های عملیاتی",
      "unit": "میلیون تومان",
      "dimensions": [
        "period"
      ]
    }
  ],
  "business_context": [
    "شرکت تولیدی-بازرگانی میانه‌حجم؛ فروش عمدتاً نسیه به شرکت‌های صنعتی و بخشی خرد",
    "دورهٔ حسابداری ماهانه؛ گزارش‌ها تا پایان همان ماه در دسترس‌اند"
  ]
}

TOOL_CALL:
{
  "tool": "get_timeseries",
  "arguments": {
    "metric": "operating_cash_flow",
    "granularity": "week",
    "range": "last_4_weeks"
  }
}

